    for (let i = 0; i < points.length - 1; i++) {
      const a = points[Math.max(0, i - 1)], b = points[i];
      const c = points[i + 1], e = points[Math.min(points.length - 1, i + 2)];
      d += "C" + coord([b[0] + (c[0] - a[0]) / 6, b[1] + (c[1] - a[1]) / 6]) + " ";
      d += coord([c[0] - (e[0] - b[0]) / 6, c[1] - (e[1] - b[1]) / 6]) + " " + coord(c);
    }
    return d;
  };
  function add(tag, attributes, parent) {
    const node = document.createElementNS(ns, tag);
    for (const [key, value] of Object.entries(attributes)) node.setAttribute(key, value);
    parent.appendChild(node);
    return node;
  }
  function path(parent, d, attributes = {}) {
    return add("path", { d, ...attributes }, parent);
  }
  function use(parent, name, transform, attributes = {}) {
    return add("use", { href: "#" + name, transform, ...attributes }, parent);
  }
  function ellipse(parent, x, y, rx, ry, attributes) {
    return add("ellipse", { cx: round(x), cy: round(y), rx: round(rx), ry: round(ry), ...attributes }, parent);
  }
  function pose(x, y, angle, sx, sy = sx) {
    return "translate(" + round(x) + " " + round(y) + ") rotate(" + round(angle) + ") scale(" + round(sx) + " " + round(sy) + ")";
