  // The print grain and the ingredients keep the same arrangement on every visit.
  let seed = 0x5939c2e1;
  function random() {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed / 4294967296;
  }
  const between = (lo, hi) => lo + random() * (hi - lo);
  const choose = array => array[Math.floor(random() * array.length)];
  function fleck(x, y, w, h, lean = 0) {
    const outline = [[-.50,.02],[-.28,-.44],[.14,-.53],[.52,-.18],[.36,.29],[-.14,.49]];
