  }

  // Project the painted arcs onto the same curved wall that defines the silhouette.
  const tilt = 134 / 350;
  const radius = v => 350 - 22 * v - 209 * v * v;
  const edge = v => Math.acos(tilt * (22 + 418 * v) / 219);
  function porcelain(angle, v) {
    const r = radius(v);
