  function parallel(v, from = -edge(v), to = edge(v)) {
    return Array.from({length: 100}, (_, i) => porcelain(from + (to - from) * i / 99, v));
  }
  function drawVessel() {
    const left = [], right = [];
    for (let i = 0; i <= 64; i++) {
      const v = i / 64;
