    const waves = add("g", {"clip-path": "url(#band-clip)", fill:"none", stroke:"url(#wave-ink)"}, bands);
    const uv = (x, y) => porcelain(x / 310, bandStart + (bandEnd - bandStart) * y / 79);
    const fullRadius = 38, rise = .79, spacing = 19.5;
    const arcs = [[], [], []];
    for (let row = 0; row < 7; row++) {
      const cy = row * spacing - 6;
