    }
    const glaze = id("glaze-marks");
    for (const [angle, width, from, to, opacity] of [[-.77,.18,.04,.94,.085],[-.98,.05,.10,.64,.10],[-.5,.13,.05,.99,.045],[.69,.30,.09,.97,.07]]) {
