    kernels.forEach(([x,y]) => use(cornPile,"corn",pose(435+x,346+y,between(-50,45),between(.74,.99),between(.68,.88))));
  }

  function drawMushroomTextures() {
    const engravings=[[],[],[],[]], chips=[[],[],[]];
