  // Each small bundle follows its own hand-drawn cubic. Offset strands separate and
  // rejoin around the bends, with a darker submerged edge and broken highlights.
  function sampleCubic(control) {
    let [x,y]=control[0], distance=0;
    const result=[];
    for(let i=1;i<control.length;i++) {
      const [ax,ay,bx,by,ex,ey]=control[i];
      const steps=Math.ceil((Math.hypot(ax-x,ay-y)+Math.hypot(bx-ax,by-ay)+Math.hypot(ex-bx,ey-by))/3.6);
      for(let j=i===1?0:1;j<=steps;j++) {
        const t=j/steps,s=1-t;
        const px=s*s*s*x+3*s*s*t*ax+3*s*t*t*bx+t*t*t*ex;
        const py=s*s*s*y+3*s*s*t*ay+3*s*t*t*by+t*t*t*ey;
        const dx=3*s*s*(ax-x)+6*s*t*(bx-ax)+3*t*t*(ex-bx);
        const dy=3*s*s*(ay-y)+6*s*t*(by-ay)+3*t*t*(ey-by);
        const length=Math.hypot(dx,dy)||1;
        if(result.length) {
          const previous=result[result.length-1];
          distance+=Math.hypot(px-previous.x,py-previous.y);
        }
        result.push({x:px,y:py,nx:-dy/length,ny:dx/length,distance});
      }
      x=ex; y=ey;
    }
    return result;
  }
