text(await tools.exec_command({cmd:`cat > <TMP>/check-ramen.cjs <<'JS'
const fs = require("node:fs");
const assert = require("node:assert/strict");
const {setTimeout:wait} = require("node:timers/promises");

(async () => {
  const tabs = await (await fetch("http://<LAN_IP>:9334/json/list")).json();
  const socket = new WebSocket(tabs.find(t=>t.type==="page").webSocketDebuggerUrl);
  await new Promise((ok,fail)=>{socket.onopen=ok;socket.onerror=fail});
  let sequence=0;
  const pending=new Map(), exceptions=[],requests=new Set();
  socket.onmessage=({data})=>{
    const message=JSON.parse(data);
    if(message.id && pending.has(message.id)) {
      const [resolve,reject]=pending.get(message.id);pending.delete(message.id);
      if(message.error) reject(new Error(JSON.stringify(message.error)));else resolve(message.result);
    }
    if(message.method==="Runtime.exceptionThrown") exceptions.push(message.params.exceptionDetails);
    if(message.method==="Network.requestWillBeSent") requests.add(message.params.request.url);
  };
  const cdp=(method,params={})=>new Promise((resolve,reject)=>{
    const id=++sequence;pending.set(id,[resolve,reject]);socket.send(JSON.stringify({id,method,params}));
  });
  const evaluate=async expression=>{
    const result=await cdp("Runtime.evaluate",{expression,returnByValue:true,awaitPromise:true});
    if(result.exceptionDetails) throw Error(result.exceptionDetails.exception.description);
    return result.result.value;
  };
  const size=(width,height)=>cdp("Emulation.setDeviceMetricsOverride",{width,height,deviceScaleFactor:1,mobile:false});
  const media=value=>cdp("Emulation.setEmulatedMedia",{features:[{name:"prefers-reduced-motion",value}]});
  const screenshot=async name=>{
    const {data}=await cdp("Page.captureScreenshot",{format:"png",captureBeyondViewport:false});
    fs.writeFileSync("<TMP>/ramen-"+name+".png",Buffer.from(data,"base64"));
  };
  const steam="document.querySelector('#steam path').getAttribute('d')";
  const load=async url=>{
    await cdp("Page.navigate",{url});
    for(let n=0;n<80;n++){
      if(await evaluate("document.readyState==='complete' && !!document.querySelector('#steam path[d^=M]')")) return;
      await wait(40);
    }
    throw Error("Scene did not initialize");
  };
  try {
    await cdp("Page.enable");await cdp("Runtime.enable");await cdp("Network.enable");
    await size(1440,900);await media("reduce");await load("http://<LAN_IP>:8139/index.html");
    await screenshot("revised");
    const initial=await evaluate(steam);
    await wait(280);
    assert.equal(await evaluate(steam),initial);
    const at=await evaluate("(()=>{const p=new DOMPoint(774,444).matrixTransform(document.getElementById('scene').getScreenCTM());return {x:p.x,y:p.y}})()");
    await cdp("Input.dispatchMouseEvent",{type:"mouseMoved",...at});
    await wait(120);
    assert.equal(await evaluate(steam),initial);
    assert.equal(await evaluate("document.querySelector('#water-reaction').childElementCount"),0);
    assert.equal(await evaluate("document.getAnimations().length"),0);
    console.log("Reduced motion holds the scene still on initial load and after pointer movement.");
    await media("no-preference");await wait(360);
    assert.notEqual(await evaluate(steam),initial);
    await cdp("Input.dispatchMouseEvent",{type:"mouseMoved",x:at.x-8,y:at.y-2});
    await wait(210);
    assert.ok((await evaluate("document.querySelector('#water-reaction').childElementCount"))>0);
    assert.ok(await evaluate("document.querySelector('#still-life').hasAttribute('transform')"));
    await wait(2100);
    assert.equal(await evaluate("document.querySelector('#water-reaction').childElementCount"),0);
    console.log("Steam animates, the mouse moves the composition, and a broth ripple appears and dissipates.");
    await media("reduce");await wait(180);
    assert.equal(await evaluate(steam),initial);
    assert.equal(await evaluate("document.querySelector('#still-life').hasAttribute('transform')"),false);
    console.log("Changing the motion preference while viewing restores the static illustration.");
    for(const [w,h] of [[320,568],[390,844],[768,1024],[844,390],[1440,900],[2560,1080]]) {
      await size(w,h);await wait(80);
      const bounds=await evaluate("(()=>{const m=document.querySelector('#scene').getScreenCTM();const a=new DOMPoint(148,212).matrixTransform(m);const b=new DOMPoint(852,692).matrixTransform(m);return [a.x,a.y,b.x,b.y,document.documentElement.scrollWidth,document.documentElement.scrollHeight]})()");
      assert.ok(bounds[0]>=0&&bounds[1]>=0&&bounds[2]<=w&&bounds[3]<=h);
      assert.ok(bounds[4]<=w&&bounds[5]<=h);
      if(w===390) await screenshot("revised-phone");
      if(w===844) await screenshot("revised-landscape");
      console.log(w+"×"+h+" fits.");
    }
    await load("file:///app/index.html");
    console.log("Standalone file loads. SVG path count",await evaluate("document.querySelectorAll('path').length"));
    assert.deepEqual([...requests].filter(u=>!u.startsWith("data:")),["http://<LAN_IP>:8139/index.html","file:///app/index.html"]);
    assert.deepEqual(exceptions,[]);
    console.log("Zero external requests and zero runtime errors.");
  } finally {
    socket.close();
  }
})().catch(e=>{console.error(e);process.exitCode=1});
